-- Freesky schema for Supabase (PostgreSQL).
--
-- Mirrors server/src/queries.rs::run_schema one-for-one — devices, community,
-- posts, reports, server_config — plus the validate_comment_parent trigger
-- from create_comment_trigger(). Idempotent: safe to re-run.
--
-- Type mapping from the SQLite original:
--   BLOB                   -> bytea
--   INTEGER PRIMARY KEY    -> bigint generated by default as identity
--   INTEGER (timestamps)   -> bigint   (epoch seconds, exactly as the Rust code writes them)
--   TEXT                   -> text
--   user_color INTEGER     -> smallint (0..15; sqlx reads it as i16, not i64)
--
-- NOTE: the server cannot use this database yet. server/src/db.rs speaks libsql
-- (Turso's protocol), not the Postgres wire protocol, so TURSO_URL=postgres://…
-- will not connect. Using Supabase requires porting the data layer to
-- sqlx/tokio-postgres — see the porting notes at the end of this file.

-- ─── Tables ───

create table if not exists devices (
    pk_dev             bytea primary key,
    user_name          text not null,
    user_color         smallint not null,
    encrypted_sk_comm  bytea,
    registered_at      bigint not null,
    banned_at          bigint,
    last_seen_at       bigint
);

create table if not exists community (
    id              integer primary key default 1,
    mls_group_state bytea,
    created_at      bigint not null,
    member_count    integer default 1,
    constraint community_id_check check (id = 1)
);

create table if not exists posts (
    id              bigint generated by default as identity primary key,
    ciphertext_comm bytea not null,
    author_pk       bytea not null references devices (pk_dev),
    author_sig      bytea not null,
    "timestamp"     bigint not null,
    mls_epoch       bigint not null,
    parent_id       bigint references posts (id)
);

create table if not exists reports (
    id          bigint generated by default as identity primary key,
    post_id     bigint not null references posts (id),
    reporter_pk bytea not null references devices (pk_dev),
    reason      text,
    reported_at bigint not null,
    resolved_at bigint,
    resolution  text
);

create table if not exists server_config (
    key   text primary key,
    value bytea not null
);

create index if not exists idx_posts_timestamp on posts ("timestamp" desc);
create index if not exists idx_posts_author on posts (author_pk);

-- ─── Comment parent validation (parity with create_comment_trigger) ───
--
-- search_path is pinned to empty and the table reference is schema-qualified.
-- Supabase's security advisor flags a role-mutable search_path on any function
-- (lint 0011); leaving it mutable means the function resolves `posts` through
-- whatever path the caller has, which is a privilege-escalation vector if a
-- caller can create objects in an earlier schema.

create or replace function public.validate_comment_parent() returns trigger
language plpgsql
set search_path = ''
as $$
begin
    if new.parent_id is not null
       and not exists (select 1 from public.posts where id = new.parent_id) then
        raise exception 'parent post not found';
    end if;
    return new;
end;
$$;

drop trigger if exists validate_comment_parent on public.posts;
create trigger validate_comment_parent
    before insert on public.posts
    for each row
    execute function public.validate_comment_parent();

-- ─── Supabase hardening ───
--
-- RLS with no policies: the auto-generated Data API (anon / authenticated keys)
-- can neither read nor write these tables, while the table owner and
-- service_role bypass RLS and keep working. Without this, everything in the
-- `public` schema is reachable through PostgREST by anyone holding the anon
-- key — which would hand out every stored ciphertext, every device public key,
-- and the community group key itself (mls_group_state).
--
-- Alternative, if you want belt and braces: put the tables in their own schema
-- (`create schema freesky;`) instead of `public`. PostgREST only exposes the
-- schemas it is configured for, so they would be unreachable through the Data
-- API at all. The cost is that every query needs `freesky.` prefixes or a
-- search_path setting.

alter table devices       enable row level security;
alter table community     enable row level security;
alter table posts         enable row level security;
alter table reports       enable row level security;
alter table server_config enable row level security;

-- ─── Verification ───
--
--   select table_name from information_schema.tables
--    where table_schema = 'public' order by table_name;
--
--   select relname, relrowsecurity from pg_class
--    where relname in ('devices','community','posts','reports','server_config');
--
-- Nothing is seeded on purpose: like the SQLite build, `community` stays empty
-- until the admin runs key rotation, and every device registration is rejected
-- with "no group key exists" until then.

-- ─── Porting notes (what a Supabase move actually costs) ───
--
-- 1. Connection: server/src/db.rs `Database` wraps libsql::Database. Replace
--    with a sqlx PgPool. AppState holds it; the pool is already Arc-friendly.
-- 2. Placeholders: every query in queries.rs uses `?`; Postgres wants `$1`.
--    Tuples like (pattern, limit) become ($1, $2).
-- 3. BLOBs: `pk_dev`, `ciphertext_comm`, `author_sig`, `encrypted_sk_comm` and
--    `mls_group_state` are Vec<u8> — map 1:1 onto bytea in sqlx.
-- 4. Affected rows: libsql's `conn.execute(…) -> u64` becomes
--    `sqlx::query(…).execute(&pool).await?.rows_affected()`.
-- 5. Dialect-specific SQL to rewrite:
--      INSERT OR REPLACE INTO server_config      -> INSERT … ON CONFLICT (key) DO UPDATE
--      hex(d.pk_dev) LIKE ?1 ESCAPE '\'          -> encode(d.pk_dev, 'hex') LIKE $1 ESCAPE '\'
--      the SQLite comment trigger                -> already translated above
--    `RETURNING id` works as-is.
-- 6. `"timestamp"` must stay quoted: it is a type name in Postgres.
-- 7. Tests: queries_test.rs runs against a file-backed libsql database. A
--    Postgres port needs a live server (or testcontainers) — the in-memory
--    trick does not carry over.
